var q=String(s||"").replace(/^\s+|\s+$/g,"");
if(!q)return[];
var p=Math.max(1,Number(page||1));
var backend="https://cdn.sofan.one:65533";
var referer="https://cdn.sofan.one/";
var ua="Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36";
var url=backend+"/s?word="+encodeURIComponent(q)+"&page="+p;
var html=String(request(url,{headers:{
    "User-Agent":ua,
    "Referer":referer,
    "Accept":"text/html,application/xhtml+xml,*/*;q=0.8",
    "Accept-Language":"zh-CN,zh;q=0.9"
},timeout:8500})||"");
if(!html)throw new Error("搜番接口空响应："+url);
if(/captcha|cloudflare|access denied|forbidden|recaptcha|challenge/i.test(html))throw new Error("搜番接口触发网页验证");
var arr=[];
try{arr=pdfa(html,"body&&.list-unstyled")||[];}catch(e){arr=[];}
var out=[],seen={};
function clean(v){return String(v||"").replace(/<[^>]+>/g," ").replace(/\s+/g," ").replace(/^\s+|\s+$/g,"");}
function abs(u){
    u=String(u||"").replace(/&amp;/g,"&").replace(/^\s+|\s+$/g,"");
    if(!u)return"";
    if(/^magnet:\?/i.test(u)||/^https?:\/\//i.test(u))return u;
    if(u.indexOf("//")===0)return "https:"+u;
    if(u.charAt(0)==="/")return backend+u;
    return backend+"/"+u.replace(/^\.\//,"");
}
function hash(v){
    var m=String(v||"").match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    if(!m)m=String(v||"").match(/([A-Fa-f0-9]{40})/);
    return m?String(m[1]).toUpperCase():"";
}
function add(title,desc,href){
    title=clean(title); desc=clean(desc); href=abs(href);
    if(!title||!href)return;
    var h=hash(href),key=String(h||href).toUpperCase();
    if(seen[key])return; seen[key]=1;
    var magnet=/^magnet:\?/i.test(href)?href:"";
    if(!magnet&&h)magnet="magnet:?xt=urn:btih:"+h+"&dn="+encodeURIComponent(title);
    out.push({title:title,desc:desc,url:magnet||href,magnet:magnet,seeders:-1,peers:-1,date:""});
}
for(var i=0;i<arr.length;i++){
    var node=arr[i],title="",desc="",href="";
    try{title=pdfh(node,"a&&Text");}catch(e1){}
    try{desc=pdfh(node,".result-resource-meta-info--.common-link&&Text");}catch(e2){}
    try{href=pdfh(node,"a&&href");}catch(e3){}
    add(title,desc,href);
}
if(!out.length){
    var m,re=/<a\b([^>]*)href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    while((m=re.exec(html))!==null){
        var href2=m[2],title2=clean(m[3]);
        if(!href2||!title2)continue;
        if(/^magnet:\?/i.test(href2)||/\/(detail|torrent|hash|resource|info|view|show)\b/i.test(href2)||/[A-Fa-f0-9]{40}/.test(href2)){
            add(title2,"",href2);
        }
        if(out.length>=80)break;
    }
}
if(!out.length)throw new Error("搜番接口已命中，但未解析到 .list-unstyled 结果；URL="+url);
return out;

