if(!u)return"";
if(/^magnet:\?/i.test(u))return u.replace(/&amp;/g,"&");
var backend="https://cdn.sofan.one:65533";
var referer="https://cdn.sofan.one/";
if(u.indexOf("//")===0)u="https:"+u;
else if(u.charAt(0)==="/")u=backend+u;
else if(!/^https?:\/\//i.test(u))u=backend+"/"+u.replace(/^\.\//,"");
