    "Referer":referer,
    "Accept":"text/html,application/xhtml+xml,*/*;q=0.8"
},timeout:8500})||"");
if(!html)throw new Error("搜番详情页空响应");
var magnet="";
try{magnet=pdfh(html,"#magnet-link&&a&&href")||"";}catch(e){}
magnet=String(magnet||"").replace(/&amp;/g,"&").replace(/^\s+|\s+$/g,"");
if(/^magnet:\?/i.test(magnet))return magnet;
var m=html.match(/magnet:\?xt=urn:btih:[^"'<> \t\r\n]+/i);
if(m)return String(m[0]).replace(/&amp;/g,"&");
var h=(html.match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i)||html.match(/([A-Fa-f0-9]{40})/));
if(h){
    var v=h[1]||h[0];
    v=String(v).replace(/^btih:/i,"").toUpperCase();
    return "magnet:?xt=urn:btih:"+v;
}
throw new Error("搜番详情页未找到 #magnet-link / magnet / InfoHash");
